t.recv(timeout=2))\\n\\n\\ndef login(client, name):\\n    correlation = request(client, \\\"login\\\", {\\\"name\\\": name})\\n    reply = receive(client)\\n    assert reply[\\\"type\\\"] == \\\"login_ok\\\"\\n    assert reply[\\\"correlation_id\\\"] == correlation\\n    assert reply[\\\"data\\\"][\\\"name\\\"] == name\\n    return reply[\\\"data\\\"]\\n\\n\\ndef sent_message(alice, bob, **extra):\\n    correlation = request(alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": \\\"hello 🌎\\\", **extra})\\n    accepted, incoming = receive(alice), receive(bob)\\n    assert accepted[\\\"type\\\"] == \\\"message_accepted\\\"\\n    assert accepted[\\\"correlation_id\\\"] == correlation\\n    assert incoming == {\\\"type\\\": \\\"message_received\\\", \\\"data\\\": accepted[\\\"data\\\"]}\\n    return accepted[\\\"data\\\"]\\nEOF\\ncat > apps/chat/tests/test_websocket.py <<'EOF'\\nimport json\\nimport time\\nfrom datetime import UTC, datetime\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom websockets.sync.client import connect\\n\\nfrom conftest import running_server\\nfrom helpers import login, receive, request, sent_message\\n\\n\\ndef test_message_ack_and_first_timestamp_pair(clients, server):\\n    alice, bob = clients\\n    sender, recipient = login(alice, \\\"alice\\\"), login(bob, \\\"bob\\\")\\n    before = datetime.now(UTC)\\n    message = sent_message(\\n        alice, bob, client_sent_at=\\\"2026-11-08T12:00:00Z\\\",\\n        server_received_at=\\\"1900-01-01T00:00:00Z\\\", sender_id=recipient[\\\"id\\\"],\\n    )\\n    UUID(message[\\\"id\\\"])\\n    assert message[\\\"sender_id\\\"] == sender[\\\"id\\\"]\\n    assert message[\\\"recipient_id\\\"] == recipient[\\\"id\\\"]\\n    assert message[\\\"text\\\"] == \\\"hello 🌎\\\"\\n    assert message[\\\"client_sent_at\\\"] == \\\"2026-11-08T12:00:00Z\\\"\\n    assert before <= datetime.fromisoformat(message[\\\"server_received_at\\\"]) <= datetime.now(UTC)\\n    assert message[\\\"recipient_received_at\\\"] is None\\n    assert message[\\\"server_ack_received_at\\\"] is None\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"],\\n                         \\\"recipient_received_at\\\": \\\"2026-11-08T12:01:00+00:00\\\",\\n                         \\\"server_ack_received_at\\\": \\\"1900-01-01T00:00:00Z\\\"})\\n    receipt = receive(alice)\\n    assert receipt[\\\"type\\\"] == \\\"delivery_receipt\\\"\\n    assert \\\"correlation_id\\\" not in receipt\\n    assert receipt[\\\"data\\\"][\\\"message_id\\\"] == message[\\\"id\\\"]\\n    assert receipt[\\\"data\\\"][\\\"recipient_received_at\\\"] == \\\"2026-11-08T12:01:00+00:00\\\"\\n    assert before <= datetime.fromisoformat(receipt[\\\"data\\\"][\\\"server_ack_received_at\\\"])\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"], \\\"recipient_received_at\\\": 17})\\n    assert receive(alice) == receipt\\n    stored = server[0].state.storage.messages[UUID(message[\\\"id\\\"])]\\n    assert stored.server_received_at == message[\\\"server_received_at\\\"]\\n    assert stored.text == message[\\\"text\\\"]\\n    # There is no separate success reply to either acknowledgment.\\n    with pytest.raises(TimeoutError):\\n        bob.recv(timeout=0.05)\\n\\n\\n@pytest.mark.parametrize(\\\"timestamp\\\", [None, 0, 42, True, {}, [], \\\"bad\\\", \\\"2026-11-08\\\",\\n                                      \\\"2026-11-08T12:00:00\\\", \\\"2026-11-08T12:00:00+01:00\\\"])\\ndef test_timestamp_fallback(clients, timestamp):\\n    alice, bob = clients\\n    login(alice, \\\"alice\\\")\\n    login(bob, \\\"bob\\\")\\n    message = sent_message(alice, bob, client_sent_at=timestamp)\\n    assert message[\\\"client_sent_at\\\"] == 0\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"], \\\"recipient_received_at\\\": timestamp})\\n    assert receive(alice)[\\\"data\\\"][\\\"recipient_received_at\\\"] == 0\\n\\n\\ndef test_missing_timestamps_and_empty_text(clients):\\n    alice, bob = clients\\n    login(alice, \\\"alice\\\")\\n    login(bob, \\\"bob\\\")\\n    message = sent_message(alice, bob, text=\\\"\\\")\\n    assert message[\\\"text\\\"] == \\\"\\\"\\n    assert message[\\\"client_sent_at\\\"] == 0\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]})\\n    assert receive(alice)[\\\"data\\\"][\\\"recipient_received_at\\\"] == 0\\n\\n\\n@pytest.mark.parametrize(\\\"name\\\", [\\\"\\\", \\\"Alice\\\", \\\"a-b\\\", \\\"a b\\\", \\\"é\\\", \\\"x\\\" * 33, \\\"alice\\\\n\\\", 1])\\ndef test_invalid_names_leave_no_user(clients, server, name):\\n    alice, _ = clients\\n    correlation = request(alice, \\\"login\\\", {\\\"name\\\": name})\\n    assert receive(alice)[\\\"correlation_id\\\"] == correlation\\n    assert server[0].state.storage.users == {}\\n    login(alice, \\\"valid_name_9\\\")\\n\\n\\ndef test_name_boundary_and_repeated_login(clients, server):\\n    alice, bob = clients\\n    first = login(alice, \\\"x\\\" * 32)\\n    for client, name in [(alice, \\\"x\\\" * 32), (alice, \\\"other\\\"), (bob, \\\"x\\\" * 32)]:\\n        correlation = request(client, \\\"login\\\", {\\\"name\\\": name})\\n        assert receive(client) == {\\\"type\\\": \\\"error\\\", \\\"correlation_id\\\": correlation,\\n                                   \\\"data\\\": {\\\"message\\\": \\\"Invalid request\\\"}}\\n    assert len(server[0].state.storage.users) == 1\\n    assert next(iter(server[0].state.sessions.connections.values())).id == UUID(first[\\\"id\\\"])\\n    login(bob, \\\"bob\\\")\\n\\n\\n@pytest.mark.parametrize(\\\"raw,valid_id\\\", [\\n    (\\\"{\\\", False), (\\\"null\\\", False), (\\\"[]\\\", False),\\n    (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": \\\"bad\\\", \\\"data\\\": {\\\"name\\\": \\\"a\\\"}}), False),\\n    (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": 123, \\\"data\\\": {\\\"name\\\": \\\"a\\\"}}), False),\\n    (json.dumps({\\\"type\\\": \\\"unknown\\\", \\\"correlation_id\\\": \\\"ID\\\", \\\"data\\\": {}}), True),\\n    (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": \\\"ID\\\", \\\"data\\\": []}), True),\\n    (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": \\\"ID\\\"}), True),\\n    (b\\\"binary\\\", False),\\n])\\ndef test_invalid_envelope_keeps_connection_usable(clients, server, raw, valid_id):\\n    alice, _ = clients\\n    correlation = str(uuid4()).upper()\\n    if isinstance(raw, str):\\n        raw = raw.replace(\\\"ID\\\", correlation)\\n    alice.send(raw)\\n    error = receive(alice)\\n    assert error[\\\"type\\\"] == \\\"error\\\"\\n    assert error.get(\\\"correlation_id\\\") == (correlation if valid_id else None)\\n    assert server[0].state.storage.users == {}\\n    login(alice, \\\"alice\\\")\\n\\n\\ndef test_valid_correlation_echo_preserves_representation(clients):\\n    alice, _ = clients\\n    correlation = str(uuid4()).upper()\\n    request(alice, \\\"login\\\", {\\\"name\\\": \\\"alice\\\"}, correlation)\\n    assert receive(alice)[\\\"correlation_id\\\"] == correlation\\n\\n\\ndef test_rejected_actions_do_not_mutate_state(clients, server):\\n    alice, bob = clients\\n    for kind, data in [(\\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": \\\"x\\\"}),\\n                       (\\\"ack\\\", {\\\"message_id\\\": str(uuid4())})]:\\n        correlation = request(alice, kind, data)\\n        assert receive(alice)[\\\"correlation_id\\\"] == correlation\\n    login(alice, \\\"alice\\\")\\n    login(bob, \\\"bob\\\")\\n    message = sent_message(alice, bob)\\n    original = dict(server[0].state.storage.messages)\\n    invalid = [\\n        (alice, \\\"send\\\", {\\\"recipient\\\": \\\"unknown\\\", \\\"text\\\": \\\"x\\\"}),\\n        (alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\"}),\\n        (alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": 7}),\\n        (alice, \\\"send\\\", {\\\"recipient\\\": 3, \\\"text\\\": \\\"x\\\"}),\\n        (alice, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]}),\\n        (bob, \\\"ack\\\", {}), (bob, \\\"ack\\\", {\\\"message_id\\\": \\\"bad\\\"}),\\n        (bob, \\\"ack\\\", {\\\"message_id\\\": str(uuid4())}),\\n    ]\\n    for client, kind, data in invalid:\\n        correlation = request(client, kind, data)\\n        reply = receive(client)\\n        assert reply[\\\"type\\\"] == \\\"error\\\"\\n        assert reply[\\\"correlation_id\\\"] == correlation\\n        assert server[0].state.storage.messages == original\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]})\\n    assert receive(alice)[\\\"type\\\"] == \\\"delivery_receipt\\\"\\n\\n\\ndef test_disconnect_persistence_offline_rejection_and_no_replay(server):\\n    app, url, _ = server\\n    with connect(url) as alice:\\n        alice_user = login(alice, \\\"alice\\\")\\n        with connect(url) as bob:\\n            bob_user = login(bob, \\\"bob\\\")\\n            message = sent_message(alice, bob)\\n        deadline = time.monotonic() + 2\\n        while UUID(bob_user[\\\"id\\\"]) in app.state.sessions.online and time.monotonic() < deadline:\\n            time.sleep(0.01)\\n        request(alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": \\\"offline\\\"})\\n        assert receive(alice)[\\\"type\\\"] == \\\"error\\\"\\n        assert len(app.state.storage.messages) == 1\\n    with connect(url) as bob:\\n        assert login(bob, \\\"bob\\\") == bob_user\\n        request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]})\\n        with pytest.raises(TimeoutError):\\n            bob.recv(timeout=0.1)\\n    with connect(url) as alice:\\n        assert login(alice, \\\"alice\\\") == alice_user\\n        with pytest.raises(TimeoutError):\\n            alice.recv(timeout=0.1)\\n\\n\\ndef test_new_server_storage_is_empty():\\n    with running_server() as (app, url, _), connect(url) as client:\\n        login(client, \\\"alice\\\")\\n        request(client, \\\"send\\\", {\\\"recipient\\\": \\\"alice\\\", \\\"text\\\": \\\"self\\\"})\\n        assert receive(client)[\\\"type\\\"] == \\\"message_received\\\"\\n        assert receive(client)[\\\"type\\\"] == \\\"message_accepted\\\"\\n        assert len(app.state.storage.users) == len(app.state.storage.messages) == 1\\n    with running_server() as (app, url, _), connect(url) as client:\\n        assert not app.state.storage.users\\n        assert not app.state.storage.messages\\n        login(client, \\\"fresh\\\")\\n        request(client, \\\"send\\\", {\\\"recipient\\\": \\\"alice\\\", \\\"text\\\": \\\"x\\\"})\\n        assert receive(client)[\\\"type\\\"] == \\\"error\\\"\\nEOF\\nuv run --project apps/chat ruff check apps/chat --fix && uv run --project apps/chat ruff format apps/chat && uv run --project apps/chat pytest apps/chat/tests/test_websocket.py -q\",\"yield_time_ms\":10000,\"max_output_tokens\":2000}));\n"
