hat\\\"\\nversion = \\\"0.1.0\\\"\\nrequires-python = \\\">=3.12\\\"\\ndependencies = [\\\"fastapi>=0.115,<1\\\", \\\"uvicorn[standard]>=0.34,<1\\\"]\\n\\n[project.scripts]\\nchat-server = \\\"chat.server:main\\\"\\n\\n[build-system]\\nrequires = [\\\"hatchling\\\"]\\nbuild-backend = \\\"hatchling.build\\\"\\n\\n[tool.hatch.build.targets.wheel]\\npackages = [\\\"chat\\\"]\\n\\n[dependency-groups]\\ndev = [\\\"pytest>=8,<10\\\", \\\"ruff>=0.11,<1\\\", \\\"websockets>=14,<17\\\"]\\n\\n[tool.ruff]\\nline-length = 100\\n\\n[tool.ruff.lint]\\nselect = [\\\"E\\\", \\\"F\\\", \\\"I\\\", \\\"UP\\\", \\\"B\\\"]\\n\\n[tool.pytest.ini_options]\\ntestpaths = [\\\"tests\\\"]\\nFROM python:3.12-slim\\nCOPY --from=ghcr.io/astral-sh/uv:0.11.1 /uv /usr/local/bin/uv\\nWORKDIR /app\\nCOPY pyproject.toml uv.lock ./\\nCOPY chat ./chat\\nRUN uv sync --frozen --no-dev\\nEXPOSE 8000\\nCMD [\\\"/app/.venv/bin/chat-server\\\"]\\n# Local chat server\\n\\nThe FastAPI server provides online messaging at `ws://localhost:8000/ws` with in-memory users and messages.\\nRun one server process so all connections share the same state.\\n\\n## Run\\n\\nFrom `apps/chat`, install the locked environment and start Uvicorn:\\n\\n```sh\\nuv sync --frozen\\nuv run chat-server\\n```\\n\\nThe server sends a standard WebSocket ping every 20 seconds and closes connections after 20 seconds without the matching pong.\\nRestarting the process discards users and messages.\\n\\n## Check\\n\\nThe test harness starts real localhost Uvicorn servers and connects with the WebSocket library and raw socket frames.\\nThe raw heartbeat scenario takes about 40 seconds and checks matching and unrelated pong behavior.\\nThe delivery failure scenario uses a real Starlette connection with a failing ASGI transport to exercise failure after storage deterministically.\\n\\n```sh\\nuv run ruff check .\\nuv run ruff format --check .\\nuv run pytest -q\\n```\\n\\nPytest reports the evidence and closes its connections, threads and listening sockets in fixture cleanup.\\nNo application clients or external services are needed.\\nThe protocol and storage contracts are in `../../specs/spec_chat/contracts/`.\\n\\n## Container\\n\\nBuild and run from `apps/chat`:\\n\\n```sh\\ndocker build -t local-chat .\\ndocker run --rm -p 8000:8000 local-chat\\n```\\nimport asyncio\\nimport logging\\nfrom dataclasses import asdict\\nfrom uuid import uuid4\\n\\nfrom starlette.websockets import WebSocket\\n\\nfrom chat import sessions, storage\\nfrom chat.handling import handle\\nfrom chat.models import User\\nfrom chat.protocol import request_adapter\\n\\n\\ndef test_storage_first_ack_is_atomic_and_users_are_stable():\\n    store = storage.Storage()\\n    assert storage.find_user(store, \\\"alice\\\") is None\\n    alice = storage.find_or_create_user(store, \\\"alice\\\")\\n    assert storage.find_or_create_user(store, \\\"alice\\\") == alice\\n    bob = storage.find_or_create_user(store, \\\"bob\\\")\\n    assert alice.id != bob.id\\n    message = storage.store_message(store, alice.id, bob.id, \\\"original\\\", 0, \\\"receive-time\\\")\\n    assert message.recipient_received_at is None\\n    assert message.server_ack_received_at is None\\n    first = storage.record_acknowledgment(store, message.id, 0, \\\"ack-time\\\")\\n    again = storage.record_acknowledgment(store, message.id, \\\"later\\\", \\\"later-ack\\\")\\n    assert first == again\\n    assert asdict(first) == {\\n        **asdict(message),\\n        \\\"recipient_received_at\\\": 0,\\n        \\\"server_ack_received_at\\\": \\\"ack-time\\\",\\n    }\\n    assert storage.find_message(store, message.id) == first\\n    assert storage.find_message(store, uuid4()) is None\\n    assert storage.Storage().users == storage.Storage().messages == {}\\n\\n\\ndef test_delivery_failure_retains_message_and_never_retries(caplog):\\n    # A real Starlette connection with a failing ASGI transport deterministically\\n    # models the failure after online validation and storage