        opcode, payload = frame(responsive)\\n        assert opcode == 1\\n        assert json.loads(payload)[\\\"type\\\"] == \\\"login_ok\\\"\\n    deadline = time.monotonic() + 3\\n    with connect(url) as reconnected:\\n        while True:\\n            request(reconnected, \\\"login\\\", {\\\"name\\\": \\\"silent\\\"})\\n            reply = receive(reconnected)\\n            if reply[\\\"type\\\"] == \\\"login_ok\\\":\\n                assert reply[\\\"data\\\"] == user\\n                break\\n            assert reply[\\\"type\\\"] == \\\"error\\\"\\n            assert time.monotonic() < deadline, \\\"Heartbeat session was not released\\\"\\n            time.sleep(0.01)\\nimport socket\\nimport threading\\nimport time\\nfrom contextlib import contextmanager\\n\\nimport pytest\\nfrom websockets.sync.client import connect\\n\\nfrom chat.api import create_app\\nfrom chat.server import create_server\\n\\n\\n@contextmanager\\ndef running_server():\\n    app = create_app()\\n    listener = socket.socket()\\n    listener.bind((\\\"127.0.0.1\\\", 0))\\n    listener.listen(128)\\n    port = listener.getsockname()[1]\\n    server = create_server(app, host=\\\"127.0.0.1\\\", port=port)\\n    thread = threading.Thread(target=server.run, kwargs={\\\"sockets\\\": [listener]}, daemon=True)\\n    thread.start()\\n    deadline = time.monotonic() + 5\\n    try:\\n        while not server.started:\\n            if not thread.is_alive() or time.monotonic() > deadline:\\n                raise RuntimeError(\\\"Server did not start\\\")\\n            time.sleep(0.01)\\n        yield f\\\"ws://127.0.0.1:{port}/ws\\\", port\\n    finally:\\n        server.should_exit = True\\n        thread.join(timeout=8)\\n        listener.close()\\n        assert not thread.is_alive(), \\\"Server failed to shut down\\\"\\n\\n\\n@pytest.fixture\\ndef server():\\n    with running_server() as running:\\n        yield running\\n\\n\\n@pytest.fixture\\ndef clients(server):\\n    with connect(server[0])