<10\\\", \\\"ruff>=0.11,<1\\\", \\\"websockets>=14,<17\\\"]\\n\\n[tool.ruff]\\nline-length = 100\\n\\n[tool.ruff.lint]\\nselect = [\\\"E\\\", \\\"F\\\", \\\"I\\\", \\\"UP\\\", \\\"B\\\"]\\n\\n[tool.pytest.ini_options]\\ntestpaths = [\\\"tests\\\"]\\nFROM python:3.12-slim\\nCOPY --from=ghcr.io/astral-sh/uv:0.11.1 /uv /usr/local/bin/uv\\nWORKDIR /app\\nCOPY pyproject.toml uv.lock ./\\nCOPY chat ./chat\\nRUN uv sync --frozen --no-dev\\nEXPOSE 8000\\nCMD [\\\"/app/.venv/bin/chat-server\\\"]\\nimport json\\n\\nfrom fastapi import FastAPI, WebSocket, WebSocketDisconnect\\nfrom pydantic import ValidationError\\n\\nfrom chat.handling import handle\\nfrom chat.protocol import correlation_id, event, request_adapter, server_timestamp\\nfrom chat.sessions import Sessions, disconnect\\nfrom chat.storage import Storage\\n\\n\\ndef create_app() -> FastAPI:\\n    app = FastAPI()\\n    store = Storage()\\n    active = Sessions()\\n\\n    @app.websocket(\\\"/ws\\\")\\n    async def websocket(connection: WebSocket) -> None:\\n        await connection.accept()\\n        try:\\n            while True:\\n                frame = await connection.receive()\\n                received_at = server_timestamp()\\n                if frame[\\\"type\\\"] == \\\"websocket.disconnect\\\":\\n                    break\\n                raw = None\\n                correlation = None\\n                try:\\n                    if \\\"text\\\" not in frame:\\n                        raise ValueError(\\\"Expected a JSON text message\\\")\\n                    raw = json.loads(frame[\\\"text\\\"])\\n                    correlation = correlation_id(raw)\\n                    # JSON-mode validation accepts wire UUID strings while retaining strict fields.\\n                    request = request_adapter.validate_json(frame[\\\"text\\\"])\\n                    reply = await handle(store, active, connection, request, received_at)\\n                    if reply is not None:\\n                        reply[\\\"correlation_id\\\"] = correlation\\n                except (ValueError, ValidationError):\\n                    reply = event(\\\"error\\\", {\\\"message\\\": \\\"Invalid request\\\"}, correlation)\\n                if reply is not None:\\n                    await connection.send_json(reply)\\n        except (WebSocketDisconnect, OSError, RuntimeError):\\n            pass\\n        finally:\\n            disconnect(active, connection)\\n\\n    return app\\nimport logging\\nfrom uuid import UUID\\n\\nfrom starlette.websockets import WebSocketDisconnect\\n\\nfrom chat.sessions import Sessions, disconnect, online_connection\\n\\nlogger = logging.getLogger(\\\"chat.delivery\\\")\\n\\n\\nasync def deliver(sessions: Sessions, user_id: UUID, event: dict) -> bool:\\n    connection = online_connection(sessions, user_id)\\n    logger.info(\\\"Delivery attempt user=%s type=%s\\\", user_id, event[\\\"type\\\"])\\n    if connection is None:\\n        logger.info(\\\"Delivery failed user=%s: disconnected\\\", user_id)\\n        return False\\n    try:\\n        await connection.send_json(event)\\n    except (OSError, RuntimeError, WebSocketDisconnect):\\n        disconnect(sessions, connection)\\n        logger.info(\\\"Delivery failed user=%s\\\", user_id, exc_info=True)\\n        return False\\n    logger.info(\\\"Delivery succeeded user=%s\\\", user_id)\\n    return True\\nfrom dataclasses import asdict\\n\\nfrom fastapi.encoders import jsonable_encoder\\nfrom starlette.websockets import WebSocket\\n\\nfrom chat import sessions, storage\\nfrom chat.delivery import deliver\\nfrom chat.protocol import Ack, Login, Send, event\\n\\n\\nasync def handle(\\n    store: storage.Storage,\\n    active: sessions.Sessions,\\n    connection: WebSocket,\\n    request: Login | Send | Ack,\\n    received_at: str,\\n) -> dict | None:\\n    correlation = str(request.correlation_id)\\n    actor = sessions.current_user(active, connection)\\n    if isinstance(request, Login):\\n        if actor is not None:\\n            raise ValueError(\\\"Connection is already logged in\\\")\\n        user = storage.find_user(store, request.data.name)\\n        if user is not None and sessions.online_connection(active, user.id) is not None:\\n            raise ValueError(\\\"User is already online\\\")\\n        user = storage.find_or_create_user(store, request.data.name)\\n        sessions.bind(active, connection, user)\\n        return event(\\\"login_ok\\\", jsonable_encoder(asdict(user)), correlation)\\n    if actor is None:\\n        raise ValueError(\\\"Login required\\\")\\n    if isinstance(request, Send):\\n        recipient = storage.find_user(store, request.data.recipient)\\n        if recipient is None:\\n            raise ValueError(\\\"Recipient does not exist\\\")\\n        if sessions.online_connection(active, recipient.id) is None:\\n            raise ValueError(\\\"Recipient is offline\\\")\\n        message = storage.store_message(\\n            store,\\n            actor.id,\\n            recipient.id,\\n            request.data.text,\\n            request.data.client_sent_at,\\n            received_at,\\n        )\\n        data = jsonable_encoder(asdict(message))\\n        await deliver(active, recipient.id, event(\\\"message_received\\\", data))\\n        return event(\\\"message_accepted\\\", data, correlation)\\n    message = storage.find_message(store, request.data.message_id)\\n    if message is None:\\n        raise ValueError(\\\"Message does not exist\\\")\\n    if message.recipient_id != actor.id:\\n        raise ValueError(\\\"Only the recipient may acknowledge this message\\\")\\n    message = storage.record_acknowledgment(\\n        store,\\n        message.id,\\n        request.data.recipient_received_at,\\n        received_at,\\n    )\\n    if sessions.online_connection(active, message.sender_id) is not None:\\n        await deliver(\\n            active,\\n            message.sender_id,\\n            event(\\n                \\\"delivery_receipt\\\",\\n                {\\n                    \\\"message_id\\\": str(message.id),\\n                    \\\"recipient_received_at\\\": message.recipient_received_at,\\n                    \\\"server_ack_received_at\\\": message.server_ack_received_at,\\n                },\\n            ),\\n        )\\n    return None\\nfrom dataclasses import dataclass\\nfrom uuid import UUID\\n\\n\\n@dataclass(frozen=True)\\nclass User:\\n    id: UUID\\n    name: str\\n\\n\\n@dataclass(frozen=True)\\nclass Message:\\n    id: UUID\\n    sender_id: UUID\\n    recipient_id: UUID\\n    text: str\\n    client_sent_at: str | int\\n    server_received_at: str\\n    recipient_received_at: str | int | None = None\\n    server_ack_received_at: str | None = None\\nfrom datetime import UTC, datetime\\nfrom typing import Annotated, Literal\\nfrom uuid import UUID\\n\\nfrom pydantic import BaseModel, BeforeValidator, ConfigDict, Field, TypeAdapter\\n\\n\\ndef client_timestamp(value: object) -> str | int:\\n    if not isinstance(value, str):\\n        return 0\\n    try:\\n        parsed = datetime.fromisoformat(value)\\n    except ValueError:\\n        return 0\\n    if \\\"T\\\" not in value or parsed.tzinfo is None or parsed.utcoffset().total_seconds() != 0:\\n        return 0\\n    return value\\n\\n\\ndef server_timestamp() -> str:\\n    return datetime.now(UTC).isoformat().replace(\\\"+00:00\\\", \\\"Z\\\")\\n\\n\\nclass Payload(BaseModel):\\n    model_config = ConfigDict(strict=True)\\n\\n\\nclass LoginData(Payload):\\n    name: str = Field(pattern=r\\\"^[a-z0-9_]{1,32}$\\\")\\n\\n\\nclass SendData(Payload):\\n    recipient: str\\n    text: str\\n    client_sent_at: Annotated[str | int, BeforeValidator(client_timestamp)] = 0\\n\\n\\nclass AckData(Payload):\\n    message_id: UUID\\n    recipient_received_at: Annotated[str | int, BeforeValidator(client_timestamp)] = 0\\n\\n\\nclass Login(BaseModel):\\n    type: Literal[\\\"login\\\"]\\n    correlation_id: UUID\\n    data: LoginData\\n\\n\\nclass Send(BaseModel):\\n    type: Literal[\\\"send\\\"]\\n    correlation_id: UUID\\n    data: SendData\\n\\n\\nclass Ack(BaseModel):\\n    type: Literal[\\\"ack\\\"]\\n    correlation_id: UUID\\n    data: AckData\\n\\n\\nrequest_adapter = TypeAdapter(Annotated[Login | Send | Ack, Field(discriminator=\\\"type\\\")])\\n\\n\\ndef correlation_id(raw: object) -> str | None:\\n    if isinstance(raw, dict) and isinstance(raw.get(\\\"correlation_id\\\"), str):\\n        try:\\n            UUID(raw[\\\"correlation_id\\\"])\\n            return raw[\\\"correlation_id\\\"]\\n        except ValueError:\\n            pass\\n    return None\\n\\n\\ndef event(kind: str, data: dict, correlation: str | None = None) -> dict:\\n    result = {\\\"type\\\": kind, \\\"data\\\": data}\\n    if correlation is not None:\\n        result[\\\"correlation_id\\\"] = correlation\\n    return result\\nimport logging\\n\\nimport uvicorn\\nfrom fastapi import FastAPI\\n\\nfrom chat.api import create_app\\n\\n\\ndef create_server(app: FastAPI, host: str = \\\"0.0.0.0\\\", port: int = 8000) -> uvicorn.Server:\\n    return uvicorn.Server(\\n        uvicorn.Config(\\n            app,\\n            host=host,\\n            port=port,\\n            workers=1,\\n            ws=\\\"websockets\\\",\\n            ws_ping_interval=20.0,\\n            ws_ping_timeout=20.0,\\n        )\\n    )\\n\\n\\ndef main() -> None:\\n    logging.basicConfig(level=logging.INFO)\\n    create_server(create_app()).run()\\n\\n\\nif __name__ == \\\"__main__\\\":\\n    main()\\nfrom dataclasses import dataclass, field\\nfrom uuid import UUID\\n\\nfrom starlette.websockets import WebSocket\\n\\nfrom chat.models import User\\n\\n\\n@dataclass\\nclass Sessions:\\n    connections: dict[WebSocket, User] = field(default_factory=dict)\\n    online: dict[UUID, WebSocket] = field(default_factory=dict)\\n\\n\\ndef current_user(sessions: Sessions, connection: WebSocket) -> User | None:\\n    return sessions.connections.get(connection)\\n\\n\\ndef online_connection(sessions: Sessions, user_id: UUID) -> WebSocket | None:\\n    return sessions.online.get(user_id)\\n\\n\\ndef bind(sessions: Sessions, connection: WebSocket, user: User) -> None:\\n    if connection in sessions.connections:\\n        raise ValueError(\\\"Connection is already logged in\\\")\\n    if user.id in sessions.online:\\n        raise ValueError(\\\"User is already online\\\")\\n    sessions.connections[connection] = user\\n    sessions.online[user.id] = connection\\n\\n\\ndef disconnect(sessions: Sessions, connection: WebSocket) -> None:\\n    user = sessions.connections.pop(connection, None)\\n    if user is not None and sessions.online.get(user.id) is connection:\\n        del sessions.online[user.id]\\nfrom dataclasses import dataclass, field, replace\\nfrom uuid import UUID, uuid4\\n\\nfrom chat.models import Message, User\\n\\n\\n@dataclass\\nclass Storage:\\n    users: dict[str, User] = field(default_factory=dict)\\n    messages: dict[UUID, Message] = field(default_factory=dict)\\n\\n\\ndef find_user(store: Storage, name: str) -> User | None:\\n    return store.users.get(name)\\n\\n\\ndef find_or_create_user(store: Storage, name: str) -> User:\\n    if name not in store.users:\\n        store.users[name] = User(uuid4(), name)\\n    return store.users[name]\\n\\n\\ndef store_message(\\n    store: Storage,\\n    sender_id: UUID,\\n    recipient_id: UUID,\\n    text: str,\\n    client_sent_at: str | int,\\n    server_received_at: str,\\n) -> Message:\\n    message = Message(uuid4(), sender_id, recipient_id, text, client_sent_at, server_received_at)\\n    store.messages[message.id] = message\\n    return message\\n\\n\\ndef find_message(store: Storage, message_id: UUID) -> Message | None:\\n    return store.messages.get(message_id)\\n\\n\\ndef record_acknowledgment(\\n    store: Storage,\\n    message_id: UUID,\\n    recipient_received_at: str | int,\\n    server_ack_received_at: str,\\n) -> Message:\\n    message = store.messages[message_id]\\n    if message.server_ack_received_at is None:\\n        message = replace(\\n            message,\\n            recipient_received_at=recipient_received_at,\\n            server_ack_received_at=server_ack_received_at,\\n        )\\n        store.messages[message_id] = message\\n    return message\\n\"}"
