eout=2))\\n\\n\\ndef login(client, name):\\n    correlation = request(client, \\\"login\\\", {\\\"name\\\": name})\\n    reply = receive(client)\\n    assert reply[\\\"type\\\"] == \\\"login_ok\\\"\\n    assert reply[\\\"correlation_id\\\"] == correlation\\n    assert reply[\\\"data\\\"][\\\"name\\\"] == name\\n    return reply[\\\"data\\\"]\\n\\n\\ndef sent_message(alice, bob, **extra):\\n    correlation = request(alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": \\\"hello 🌎\\\", **extra})\\n    accepted, incoming = receive(alice), receive(bob)\\n    assert accepted[\\\"type\\\"] == \\\"message_accepted\\\"\\n    assert accepted[\\\"correlation_id\\\"] == correlation\\n    assert incoming == {\\\"type\\\": \\\"message_received\\\", \\\"data\\\": accepted[\\\"data\\\"]}\\n    return accepted[\\\"data\\\"]\\nimport base64\\nimport hashlib\\nimport json\\nimport os\\nimport socket\\nimport struct\\nimport time\\nfrom contextlib import contextmanager\\nfrom uuid import uuid4\\n\\nfrom helpers import receive, request\\nfrom websockets.sync.client import connect\\n\\n\\ndef exact(sock, size):\\n    result = b\\\"\\\"\\n    while len(result) < size:\\n        chunk = sock.recv(size - len(result))\\n        if not chunk:\\n            raise EOFError(\\\"Connection closed\\\")\\n        result += chunk\\n    return result\\n\\n\\ndef frame(sock):\\n    first, second = exact(sock, 2)\\n    size = second & 127\\n    if size == 126:\\n        size = struct.unpack(\\\"!H\\\", exact(sock, 2))[0]\\n    elif size == 127:\\n        size = struct.unpack(\\\"!Q\\\", exact(sock, 8))[0]\\n    assert second & 128 == 0\\n    return first & 15, exact(sock, size)\\n\\n\\ndef send_frame(sock, opcode, payload):\\n    mask = os.urandom(4)\\n    size = len(payload)\\n    header = (\\n        bytes([128 | opcode, 128 | size])\\n        if size < 126\\n        else (bytes([128 | opcode, 128 | 126]) + struct.pack(\\\"!H\\\", size))\\n    )\\n    masked = bytes(byte ^ mask[index 