t satisfy the outstanding server ping.\\n        send_frame(silent, 10, b\\\"not-the-ping-payload\\\")\\n        opcode, second_ping = frame(responsive)\\n        assert opcode == 9\\n        send_frame(responsive, 10, second_ping)\\n        opcode, close = frame(silent)\\n        assert opcode == 8\\n        assert struct.unpack(\\\"!H\\\", close[:2])[0] == 1011\\n        assert 38 <= time.monotonic() - start <= 44\\n        send_frame(silent, 8, close)\\n        # Responsive connection remains usable after two matching pongs.\\n        send_frame(\\n            responsive,\\n            1,\\n            json.dumps(\\n                {\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": str(uuid4()), \\\"data\\\": {\\\"name\\\": \\\"responsive\\\"}}\\n            ).encode(),\\n        )\\n        opcode, payload = frame(responsive)\\n        assert opcode == 1\\n        assert json.loads(payload)[\\\"type\\\"] == \\\"login_ok\\\"\\n    deadline = time.monotonic() + 3\\n    with connect(url) as reconnected:\\n        while True:\\n            request(reconnected, \\\"login\\\", {\\\"name\\\": \\\"silent\\\"})\\n            reply = receive(reconnected)\\n            if reply[\\\"type\\\"] == \\\"login_ok\\\":\\n                assert reply[\\\"data\\\"] == user\\n                break\\n            assert reply[\\\"type\\\"] == \\\"error\\\"\\n            assert time.monotonic() < deadline, \\\"Heartbeat session was not released\\\"\\n            time.sleep(0.01)\\nimport asyncio\\nimport logging\\nfrom dataclasses import asdict\\nfrom uuid import uuid4\\n\\nfrom starlette.websockets import WebSocket\\n\\nfrom chat import sessions, storage\\nfrom chat.handling import handle\\nfrom chat.models import User\\nfrom chat.protocol import request_adapter\\n\\n\\ndef test_storage_first_ack_is_atomic_and_users_are_stable():\\n    store = storage.Storage()\\n    assert storage.find_user(store, \\\"alice\\\") is None\\n    alice = storage.find_or_create_user(store, \\\"alice\\\")\\n    assert storage.find_or_create_user(store, \\\"alice\\\") == alice\\n    bob = storage.find_or_create_user(store, \\\"bob\\\")\\n    assert alice.id != bob.id\\n    message = storage.store_message(store, alice.id, bob.id, \\\"original\\\", 0, \\\"receive-time\\\")\\n    assert message.recipient_received_at is None\\n    assert message.server_ack_received_at is None\\n    first = storage.record_acknowledgment(store, message.id, 0, \\\"ack-time\\\")\\n    again = storage.record_acknowledgment(store, message.id, \\\"later\\\", \\\"later-ack\\\")\\n    assert first == again\\n    assert asdict(first) == {\\n        **asdict(message),\\n        \\\"recipient_received_at\\\": 0,\\n        \\\"server_ack_received_at\\\": \\\"ack-time\\\",\\n    }\\n    assert storage.find_message(store, message.id) == first\\n    assert storage.find_message(store, uuid4()) is None\\n    assert storage.Storage().users == storage.Storage().messages == {}\\n\\n\\ndef test_delivery_failure_retains_message_and_never_retries(caplog):\\n    # A real Starlette connection with a failing ASGI transport deterministically\\n    # models the failure after online validation and storage, without a socket race.\\n    transport_calls = []\\n\\n    async def receive():\\n        return {\\\"type\\\": \\\"websocket.connect\\\"}\\n\\n    async def broken_send(frame):\\n        transport_calls.append(frame)\\n        if frame[\\\"type\\\"] == \\\"websocket.send\\\":\\n            raise OSError(\\\"transport lost\\\")\\n\\n    async def normal_send(frame):\\n        pass\\n\\n    async def scenario():\\n        alice_connection = WebSocket({\\\"type\\\": \\\"websocket\\\"}, receive, normal_send)\\n        bob_connection = WebSocket({\\\"type\\\": \\\"websocket\\\"}, receive, broken_send)\\n        await alice_connection.accept()\\n        await bob_connection.accept()\\n        transport_calls.clear()\\n        store, active = storage.Storage(), sessions.Sessions()\\n        alice, bob = (storage.find_or_create_user(store, name) for name in (\\\"alice\\\", \\\"bob\\\"))\\n        sessions.bind(active, alice_connection, alice)\\n        sessions.bind(active, bob_connection, bob)\\n        request = request_adapter.validate_json(\\n            '{\\\"type\\\":\\\"send\\\",\\\"correlation_id\\\":\\\"'\\n            + str(uuid4())\\n            + '\\\",\\\"data\\\":{\\\"recipient\\\":\\\"bob\\\",\\\"text\\\":\\\"retained\\\"}}'\\n        )\\n        reply = await handle(store, active, alice_connection, request, \\\"event-received-time\\\")\\n        assert reply[\\\"type\\\"] == \\\"message_accepted\\\"\\n        assert len(store.messages) == 1\\n        message = next(iter(store.messages.values()))\\n        assert message.text == \\\"retained\\\"\\n        assert message.server_received_at == \\\"event-received-time\\\"\\n        assert message.server_ack_received_at is None\\n        assert sessions.online_connection(active, bob.id) is None\\n        assert sessions.current_user(active, bob_connection) is None\\n        assert sessions.current_user(active, alice_connection) == alice\\n        assert len(transport_calls) == 1\\n        await asyncio.sleep(0.05)\\n        assert len(transport_calls) == 1\\n        return active, alice_connection, bob\\n\\n    with caplog.at_level(logging.INFO, logger=\\\"chat.delivery\\\"):\\n        asyncio.run(scenario())\\n    assert sum(\\\"Delivery attempt\\\" in record.message for record in caplog.records) == 1\\n    assert sum(\\\"Delivery failed\\\" in record.message for record in caplog.records) == 1\\n\\n\\ndef test_session_resolver_prevents_duplicate_and_rebinding():\\n    active = sessions.Sessions()\\n    # Resolver behavior doesn't depend on transport methods.\\n    first, second = object(), object()\\n    alice, bob = User(uuid4(), \\\"alice\\\"), User(uuid4(), \\\"bob\\\")\\n    sessions.bind(active, first, alice)\\n    for connection, user in [(first, alice), (first, bob), (second, alice)]:\\n        try:\\n            sessions.bind(active, connection, user)\\n        except ValueError:\\n            pass\\n        else:\\n            raise AssertionError(\\\"Duplicate login was permitted\\\")\\n    assert sessions.current_user(active, first) == alice\\n    sessions.disconnect(active, first)\\n    sessions.disconnect(active, first)\\n    sessions.bind(active, second, alice)\\n    assert sessions.online_connection(active, alice.id) is second\\nimport json\\nimport time\\nfrom datetime import UTC, datetime\\nfrom uuid import UUID, uuid4\\n\\nimport pytest\\nfrom conftest import running_server\\nfrom helpers import login, receive, request, sent_message\\nfrom websockets.sync.client import connect\\n\\n\\ndef test_message_ack_and_first_timestamp_pair(clients):\\n    alice, bob = clients\\n    sender, recipient = login(alice, \\\"alice\\\"), login(bob, \\\"bob\\\")\\n    before = datetime.now(UTC)\\n    message = sent_message(\\n        alice,\\n        bob,\\n        client_sent_at=\\\"2026-11-08T12:00:00Z\\\",\\n        server_received_at=\\\"1900-01-01T00:00:00Z\\\",\\n        sender_id=recipient[\\\"id\\\"],\\n    )\\n    UUID(message[\\\"id\\\"])\\n    assert message[\\\"sender_id\\\"] == sender[\\\"id\\\"]\\n    assert message[\\\"recipient_id\\\"] == recipient[\\\"id\\\"]\\n    assert message[\\\"text\\\"] == \\\"hello 🌎\\\"\\n    assert message[\\\"client_sent_at\\\"] == \\\"2026-11-08T12:00:00Z\\\"\\n    assert before <= datetime.fromisoformat(message[\\\"server_received_at\\\"]) <= datetime.now(UTC)\\n    assert message[\\\"recipient_received_at\\\"] is None\\n    assert message[\\\"server_ack_received_at\\\"] is None\\n    request(\\n        bob,\\n        \\\"ack\\\",\\n        {\\n            \\\"message_id\\\": message[\\\"id\\\"],\\n            \\\"recipient_received_at\\\": \\\"2026-11-08T12:01:00+00:00\\\",\\n            \\\"server_ack_received_at\\\": \\\"1900-01-01T00:00:00Z\\\",\\n        },\\n    )\\n    receipt = receive(alice)\\n    assert receipt[\\\"type\\\"] == \\\"delivery_receipt\\\"\\n    assert \\\"correlation_id\\\" not in receipt\\n    assert receipt[\\\"data\\\"][\\\"message_id\\\"] == message[\\\"id\\\"]\\n    assert receipt[\\\"data\\\"][\\\"recipient_received_at\\\"] == \\\"2026-11-08T12:01:00+00:00\\\"\\n    assert before <= datetime.fromisoformat(receipt[\\\"data\\\"][\\\"server_ack_received_at\\\"])\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"], \\\"recipient_received_at\\\": 17})\\n    assert receive(alice) == receipt\\n    # There is no separate success reply to either acknowledgment.\\n    with pytest.raises(TimeoutError):\\n        bob.recv(timeout=0.05)\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"timestamp\\\",\\n    [\\n        None,\\n        0,\\n        42,\\n        True,\\n        {},\\n        [],\\n        \\\"bad\\\",\\n        \\\"2026-11-08\\\",\\n        \\\"2026-11-08T12:00:00\\\",\\n        \\\"2026-11-08T12:00:00+01:00\\\",\\n    ],\\n)\\ndef test_timestamp_fallback(clients, timestamp):\\n    alice, bob = clients\\n    login(alice, \\\"alice\\\")\\n    login(bob, \\\"bob\\\")\\n    message = sent_message(alice, bob, client_sent_at=timestamp)\\n    assert message[\\\"client_sent_at\\\"] == 0\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"], \\\"recipient_received_at\\\": timestamp})\\n    assert receive(alice)[\\\"data\\\"][\\\"recipient_received_at\\\"] == 0\\n\\n\\ndef test_missing_timestamps_and_empty_text(clients):\\n    alice, bob = clients\\n    login(alice, \\\"alice\\\")\\n    login(bob, \\\"bob\\\")\\n    message = sent_message(alice, bob, text=\\\"\\\")\\n    assert message[\\\"text\\\"] == \\\"\\\"\\n    assert message[\\\"client_sent_at\\\"] == 0\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]})\\n    assert receive(alice)[\\\"data\\\"][\\\"recipient_received_at\\\"] == 0\\n\\n\\n@pytest.mark.parametrize(\\\"name\\\", [\\\"\\\", \\\"Alice\\\", \\\"a-b\\\", \\\"a b\\\", \\\"é\\\", \\\"x\\\" * 33, \\\"alice\\\\n\\\", 1])\\ndef test_invalid_names_keep_connection_usable(clients, name):\\n    alice, _ = clients\\n    correlation = request(alice, \\\"login\\\", {\\\"name\\\": name})\\n    assert receive(alice)[\\\"correlation_id\\\"] == correlation\\n    login(alice, \\\"valid_name_9\\\")\\n\\n\\ndef test_name_boundary_and_repeated_login(clients):\\n    alice, bob = clients\\n    first = login(alice, \\\"x\\\" * 32)\\n    for client, name in [(alice, \\\"x\\\" * 32), (alice, \\\"other\\\"), (bob, \\\"x\\\" * 32)]:\\n        correlation = request(client, \\\"login\\\", {\\\"name\\\": name})\\n        assert receive(client) == {\\n            \\\"type\\\": \\\"error\\\",\\n            \\\"correlation_id\\\": correlation,\\n            \\\"data\\\": {\\\"message\\\": \\\"Invalid request\\\"},\\n        }\\n    login(bob, \\\"bob\\\")\\n    assert sent_message(alice, bob)[\\\"sender_id\\\"] == first[\\\"id\\\"]\\n\\n\\n@pytest.mark.parametrize(\\n    \\\"raw,valid_id\\\",\\n    [\\n        (\\\"{\\\", False),\\n        (\\\"null\\\", False),\\n        (\\\"[]\\\", False),\\n        (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": \\\"bad\\\", \\\"data\\\": {\\\"name\\\": \\\"a\\\"}}), False),\\n        (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": 123, \\\"data\\\": {\\\"name\\\": \\\"a\\\"}}), False),\\n        (json.dumps({\\\"type\\\": \\\"unknown\\\", \\\"correlation_id\\\": \\\"ID\\\", \\\"data\\\": {}}), True),\\n        (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": \\\"ID\\\", \\\"data\\\": []}), True),\\n        (json.dumps({\\\"type\\\": \\\"login\\\", \\\"correlation_id\\\": \\\"ID\\\"}), True),\\n        (b\\\"binary\\\", False),\\n    ],\\n)\\ndef test_invalid_envelope_keeps_connection_usable(clients, raw, valid_id):\\n    alice, _ = clients\\n    correlation = str(uuid4()).upper()\\n    if isinstance(raw, str):\\n        raw = raw.replace(\\\"ID\\\", correlation)\\n    alice.send(raw)\\n    error = receive(alice)\\n    assert error[\\\"type\\\"] == \\\"error\\\"\\n    assert error.get(\\\"correlation_id\\\") == (correlation if valid_id else None)\\n    login(alice, \\\"alice\\\")\\n\\n\\ndef test_valid_correlation_echo_preserves_representation(clients):\\n    alice, _ = clients\\n    correlation = str(uuid4()).upper()\\n    request(alice, \\\"login\\\", {\\\"name\\\": \\\"alice\\\"}, correlation)\\n    assert receive(alice)[\\\"correlation_id\\\"] == correlation\\n\\n\\ndef test_rejected_actions_leave_message_unacknowledged_and_connections_usable(clients):\\n    alice, bob = clients\\n    for kind, data in [\\n        (\\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": \\\"x\\\"}),\\n        (\\\"ack\\\", {\\\"message_id\\\": str(uuid4())}),\\n    ]:\\n        correlation = request(alice, kind, data)\\n        assert receive(alice)[\\\"correlation_id\\\"] == correlation\\n    login(alice, \\\"alice\\\")\\n    login(bob, \\\"bob\\\")\\n    message = sent_message(alice, bob)\\n    invalid = [\\n        (alice, \\\"send\\\", {\\\"recipient\\\": \\\"unknown\\\", \\\"text\\\": \\\"x\\\"}),\\n        (alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\"}),\\n        (alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": 7}),\\n        (alice, \\\"send\\\", {\\\"recipient\\\": 3, \\\"text\\\": \\\"x\\\"}),\\n        (\\n            alice,\\n            \\\"ack\\\",\\n            {\\\"message_id\\\": message[\\\"id\\\"], \\\"recipient_received_at\\\": \\\"2026-11-08T12:00:00Z\\\"},\\n        ),\\n        (bob, \\\"ack\\\", {}),\\n        (bob, \\\"ack\\\", {\\\"message_id\\\": \\\"bad\\\"}),\\n        (bob, \\\"ack\\\", {\\\"message_id\\\": str(uuid4())}),\\n    ]\\n    for client, kind, data in invalid:\\n        correlation = request(client, kind, data)\\n        reply = receive(client)\\n        assert reply[\\\"type\\\"] == \\\"error\\\"\\n        assert reply[\\\"correlation_id\\\"] == correlation\\n    request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]})\\n    receipt = receive(alice)\\n    assert receipt[\\\"type\\\"] == \\\"delivery_receipt\\\"\\n    assert receipt[\\\"data\\\"][\\\"recipient_received_at\\\"] == 0\\n    with pytest.raises(TimeoutError):\\n        bob.recv(timeout=0.05)\\n    with pytest.raises(TimeoutError):\\n        alice.recv(timeout=0.05)\\n\\n\\ndef test_disconnect_persistence_offline_rejection_and_no_replay(server):\\n    url, _ = server\\n    with connect(url) as alice:\\n        alice_user = login(alice, \\\"alice\\\")\\n        with connect(url) as bob:\\n            bob_user = login(bob, \\\"bob\\\")\\n            message = sent_message(alice, bob)\\n        deadline = time.monotonic() + 2\\n        while True:\\n            request(alice, \\\"send\\\", {\\\"recipient\\\": \\\"bob\\\", \\\"text\\\": \\\"offline\\\"})\\n            reply = receive(alice)\\n            if reply[\\\"type\\\"] == \\\"error\\\":\\n                break\\n            assert reply[\\\"type\\\"] == \\\"message_accepted\\\"\\n            assert time.monotonic() < deadline, \\\"Disconnect was not detected\\\"\\n            time.sleep(0.01)\\n    with connect(url) as bob:\\n        assert login(bob, \\\"bob\\\") == bob_user\\n        request(bob, \\\"ack\\\", {\\\"message_id\\\": message[\\\"id\\\"]})\\n        with pytest.raises(TimeoutError):\\n            bob.recv(timeout=0.1)\\n    with connect(url) as alice:\\n        assert login(alice, \\\"alice\\\") == alice_user\\n        with pytest.raises(TimeoutError):\\n            alice.recv(timeout=0.1)\\n\\n\\ndef test_new_server_discards_users_and_messages():\\n    with running_server() as (url, _), connect(url) as client:\\n        original_user = login(client, \\\"alice\\\")\\n        request(client, \\\"send\\\", {\\\"recipient\\\": \\\"alice\\\", \\\"text\\\": \\\"self\\\"})\\n        incoming = receive(client)\\n        assert incoming[\\\"type\\\"] == \\\"message_received\\\"\\n        assert receive(client)[\\\"type\\\"] == \\\"message_accepted\\\"\\n    with running_server() as (url, _), connect(url) as client:\\n        assert login(client, \\\"alice\\\")[\\\"id\\\"] != original_user[\\\"id\\\"]\\n        request(client, \\\"ack\\\", {\\\"message_id\\\": incoming[\\\"data\\\"][\\\"id\\\"]})\\n        assert receive(client)[\\\"type\\\"] == \\\"error\\\"\\n\"}}"
